package org.jetlinks.pro.property.quality.service;
import org.junit.jupiter.api.Test;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.hswebframework.web.exception.BusinessException;
import java.io.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class QualityWorkbookTest {
 private byte[] workbook(String target,int level,List<List<String>> data,boolean formula)throws IOException{try(var book=new XSSFWorkbook();var bytes=new ByteArrayOutputStream()){var sheet=book.createSheet("导入");var headers=QualityWorkbook.headers(target,level);var row=sheet.createRow(0);for(int i=0;i<headers.size();i++)row.createCell(i).setCellValue(headers.get(i)+" *");for(int i=0;i<data.size();i++){row=sheet.createRow(i+1);for(int j=0;j<data.get(i).size();j++)row.createCell(j).setCellValue(data.get(i).get(j));}if(formula)sheet.getRow(1).getCell(0).setCellFormula("1+1");book.write(bytes);return bytes.toByteArray();}}
 @Test void emptyCellsInheritHierarchyAndPreservePhysicalRows()throws Exception{var rows=QualityWorkbook.parse(workbook("basic",1,List.of(List.of("环境","绿化","草坪","覆盖率","现场全景","启用"),List.of("","","树木","树木无枯枝","近景","禁用")),false),"basic",1);assertEquals(2,rows.size());assertEquals("环境",rows.get(1).line());assertEquals("绿化",rows.get(1).subject());assertEquals(3,rows.get(1).row());assertEquals(0,rows.get(1).status());}
 @Test void taskImportKeepsNegativeDeductionDescriptionAndZeroScore()throws Exception{var rows=QualityWorkbook.parse(workbook("task",2,List.of(List.of("项目A","秩序","门岗","值班","0","每项扣2分","每周","启用")),false),"task",2);assertEquals(0,rows.get(0).score());assertEquals(2,rows.get(0).frequency());assertEquals("每项扣2分",rows.get(0).deduction());}
 @Test void malformedScoreRejectsEntireWorkbook()throws Exception{var bytes=workbook("task",1,List.of(List.of("项目A","环境","绿化","草坪","10","","启用"),List.of("","","树木","2.5","","启用")),false);assertThrows(BusinessException.class,()->QualityWorkbook.parse(bytes,"task",1));}
 @Test void formulasAreNeverEvaluated()throws Exception{var bytes=workbook("subjects",1,List.of(List.of("环境","绿化","启用")),true);assertThrows(BusinessException.class,()->QualityWorkbook.parse(bytes,"subjects",1));}
 @Test void missingHeadersAndEmptyWorkbookAreRejected()throws Exception{var bytes=workbook("subjects",1,List.of(),false);assertThrows(BusinessException.class,()->QualityWorkbook.parse(bytes,"subjects",1));assertThrows(BusinessException.class,()->QualityWorkbook.parse(bytes,"basic",1));}
}
